function mesh(geo,m,parent,x=0,y=0,z=0){const a=new T.Mesh(geo,m);a.position.set(x,y,z);a.castShadow=true;a.receiveShadow=true;parent.add(a);return a;}
function cylinder(parent,rt,rb,h,color,x,y,z,sides=12){return mesh(new T.CylinderGeometry(rt,rb,h,sides),mat(color),parent,x,y,z);}
function box(parent,w,h,d,color,x,y,z){return mesh(new T.BoxGeometry(w,h,d),mat(color),parent,x,y,z);}
function ring(parent,r,tube,color,y){const a=mesh(new T.TorusGeometry(r,tube,6,44),mat(color),parent,0,y,0);a.rotation.x=Math.PI/2;return a;}
