function palm(parent,x,z,scale=1,seed=0){const g=new T.Group();g.position.set(x,1,z);g.scale.setScalar(scale);parent.add(g);const trunk=cylinder(g,.16,.29,4.6,'#97705a',.3,2.3,0,7);trunk.rotation.z=-.14;const crown=new T.Group();crown.position.set(.62,4.6,0);g.add(crown);for(let i=0;i<7;i++){const leaf=mesh(new T.ConeGeometry(.72,3.4,4),mat(i%2?'#3a8469':'#65a57a'),crown);leaf.rotation.z=1.2;const lg=new T.Group();lg.rotation.y=i*Math.PI*2/7+seed;lg.add(leaf);leaf.position.x=1.35;crown.add(lg);}return g;}
