 textLabel(g,e.name.toUpperCase(),9.3,'#fff7df',1.15);textLabel(g,e.label,11.4,e.color,.35);
 if(e.id==='halloween'){for(let i=0;i<9;i++){const a=i*2.4;const r=3.3+rand(i+4)*3;const pg=new T.Group();pg.position.set(Math.cos(a)*r,1.9,Math.sin(a)*r);g.add(pg);const pumpkin=mesh(new T.SphereGeometry(.65,9,6),mat('#f37e32'),pg);pumpkin.scale.y=.8;cylinder(pg,.07,.09,.25,'#547457',0,.63,0,5);for(const x of [-.22,.22])mesh(new T.ConeGeometry(.13,.22,3),mat('#352f34'),pg,x,.1,.56);}palm(g,-5,0,.85);palm(g,5,-4,.95);}
 else if(e.id==='christmas'){for(const [x,z,sz] of [[-5,-3,1.1],[5,-4,.85],[-4,4,.7],[4,4,.6]]){const tree=new T.Group();tree.position.set(x,1.8,z);tree.scale.setScalar(sz);g.add(tree);cylinder(tree,.22,.3,1,'#826d54',0,.5,0,7);for(let i=0;i<3;i++)mesh(new T.ConeGeometry(1.8-i*.38,2.5,9),mat(i%2?'#579281':'#285e56'),tree,0,1.6+i*1.15,0);mesh(new T.OctahedronGeometry(.36),mat('#ffe199'),tree,0,5.6,0);for(let i=0;i<8;i++)mesh(new T.SphereGeometry(.12,6,6),mat('#ffe4b3'),tree,Math.sin(i*2)*1.25,1.3+i*.36,Math.cos(i*2)*1.25);}}
 else{palm(g,-6,2,1.25);palm(g,6,-3,1.1);const arch=new T.Group();arch.position.set(0,2,5);g.add(arch);const ar=mesh(new T.TorusGeometry(2.8,.13,8,48,Math.PI),mat('#f6d794'),arch,0,1,0);for(const x of [-2.8,2.8])cylinder(arch,.13,.13,1.5,'#f6d794',x,.3,0);textLabel(arch,'THE LAST DANCE',2.2,'#fff2c4',.58);}
 for(let i=0;i<16;i++){const a=i*2.399,r=3+rand(i+11)*3.6;const person=new T.Group();person.position.set(Math.cos(a)*r,1.84,Math.sin(a)*r+1);person.rotation.y=rand(i)*6;g.add(person);cylinder(person,.13,.16,.65,['#fa9c77','#bdc7cc','#76c4b4','#e4cea1'][i%4],0,.48,0,6);mesh(new T.SphereGeometry(.16,8,8),mat('#c89572'),person,0,.92,0);}
